.toolbar label, .toolbar select { margin: 0; }
.toolbar select { width: auto; }
.metrics { gap: 12px; margin-bottom: 16px; }
.metrics .card { padding: 16px; border-radius: 8px; min-width: 0; font-weight: 650; }
